Templates.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/forms.FormView */}}
{{/* Starting point generated by WebThings: a complete working form. */}}
<main id="content">
    <h1>{{.Title}}</h1>

    {{if .Sent}}
        <div>{{.Success}}</div>
    {{else}}
        <div>{{.Intro}}</div>

        {{if .Throttled}}<p>You sent this form several times already. Please try again later.</p>{{end}}
        {{if .Invalid}}<p>Please check the marked fields.</p>{{end}}

        {{form_render .Form .Errors}}
    {{end}}
</main>

Mail.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/forms.NotifyView */}}
{{/* Sent to the form's notification address for every submission, in the admin's language. */}}
{{define "subject"}}{{.Title}}{{end}}

{{define "text"}}
{{range .Answers -}}
{{.Label}}:
{{or .Value "-"}}

{{end -}}
{{.SubmissionURL}}
{{end}}

Types.Decl:
type Answer struct {
	Name  string `json:"name"`
	Label string `json:"label"`
	Value string `json:"value"`
}

type Definition struct {
	Fields FieldList `db:"form_fields"`
	Notify string    `db:"notify"`
}

type Field struct {
	Name     string   `json:"name"`
	Type     string   `json:"type"`
	Required bool     `json:"required,omitempty"`
	Options  []string `json:"options,omitempty"`
}

type FormView struct {
	Title string
	Intro template.HTML
	// Action is the URL the form posts to: the page itself.
	Action string
	// Form is the form's model: its fields as the editor defined them, in
	// the page's language, with the visitor's answers after a post with
	// errors, for go-form's template functions, such as {{form_render
	// .Form .Errors}}, or {{form_open .Form}} with {{form_field .Form name
	// .Errors}} per name of Fields. form_open adds the spam trap
	// (frontend.Honeypot), and the fields' ids start with the instance key.
	Form form.RenderModel
	// Fields are the names of the form's fields, in order, for form_field.
	Fields []string
	// Errors are the problems of a post per field, with messages in the
	// page's language, which form_field and form_render show at their
	// fields; empty otherwise.
	Errors form.FieldErrors
	// Invalid is set when a submission has errors; see Errors.
	Invalid bool
	// Throttled is set when the visitor sent the form too often in a short
	// time. Nothing was stored; the form is shown with their answers, to send
	// again later.
	Throttled bool
	// Sent is set after a successful submission; show Success instead of the form.
	Sent    bool
	Success template.HTML
}

type InboxView struct {
	Title   string
	BackURL string
	// TrashURL shows the deleted submissions in the admin's trash.
	TrashURL string
	// Filters switch between new, archived and all submissions.
	Filters admin.Tabs
	Rows    []InboxRow
	Pager   admin.Pager
}

type Label struct {
	Label       string            `json:"label"`
	Placeholder string            `json:"placeholder,omitempty"`
	Help        string            `json:"help,omitempty"`
	Options     map[string]string `json:"options,omitempty"`
}

type NotifyView struct {
	// Title is the form's title in the language the visitor used.
	Title string
	// Locale is the language the visitor used.
	Locale string
	// Answers are the submitted values, each with the label the visitor saw.
	Answers Answers
	// ReplyTo is the first address the visitor gave in an email field; empty
	// when there is none.
	ReplyTo string
	// SubmissionURL opens the submission in the admin.
	SubmissionURL string
}

type Service struct {
	// contains unexported fields
}

type Text struct {
	Title   string `db:"title"`
	Intro   string `db:"intro"`
	Success string `db:"success"`
	Labels  Labels `db:"field_labels"`
}
